// Keep a self-contained asset declaration for artifact.html, like the existing painted packs.
const fs=require('fs'),path=require('path');
const root=path.join(__dirname,'..'),file=path.join(root,'assets/combat-fx/effects.png');
const data=fs.readFileSync(file);
fs.writeFileSync(path.join(root,'js/combat-assets.js'),
  '// Generated by tools/pack-combat-art.cjs from assets/combat-fx/effects.png.\n'+
  'const COMBAT_ASSETS = { sheet: '+JSON.stringify('data:image/png;base64,'+data.toString('base64'))+' };\n');
